// 1. Kiểm tra Status code trả về là 200 OK
pm.test("Kiểm tra Status code is 200", function () {
    pm.response.to.have.status(200);
});

// 2. Trích xuất token từ JSON response và lưu tự động vào biến môi trường userToken
pm.test("Trích xuất và lưu userToken vào Environment", function () {
    var jsonData = pm.response.json();
    pm.expect(jsonData).to.have.property("token");
    pm.expect(jsonData.token).to.be.a("string").and.not.empty;
    pm.environment.set("userToken", jsonData.token);
});

// 1. Kiểm tra Status code trả về là 201 Created
pm.test("Kiểm tra Status code is 201", function () {
    pm.response.to.have.status(201);
});

let resBody = pm.response.json();

// 2. Kiểm tra dữ liệu name và job trong response body
pm.test("Kiểm tra trường name và job trong response khớp đúng dữ liệu", function () {
    if (pm.iterationData && pm.iterationData.get("name")) {
        pm.expect(resBody.name).to.eql(pm.iterationData.get("name"));
        pm.expect(resBody.job).to.eql(pm.iterationData.get("job"));
    } else if (pm.request.body && pm.request.body.raw) {
        const reqBody = JSON.parse(pm.request.body.raw);
        pm.expect(resBody.name).to.eql(reqBody.name);
        pm.expect(resBody.job).to.eql(reqBody.job);
    }
});

// 3. Trích xuất id trả về và gán vào biến môi trường userId
pm.test("Trích xuất id trả về và gán vào biến môi trường userId", function () {
    pm.expect(resBody).to.have.property("id");
    pm.environment.set("userId", resBody.id);
});

